1	package cli
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"io"
8		"path/filepath"
9		"strings"
10	
11		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
12		checkpointid "github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
13		"github.com/entireio/cli/cmd/entire/cli/facets"
14		"github.com/entireio/cli/cmd/entire/cli/githubidentity"
15		"github.com/entireio/cli/cmd/entire/cli/insightsdb"
16		"github.com/entireio/cli/cmd/entire/cli/llmcli"
17		"github.com/entireio/cli/cmd/entire/cli/logging"
18		"github.com/entireio/cli/cmd/entire/cli/paths"
19		"github.com/entireio/cli/cmd/entire/cli/settings"
20		"github.com/entireio/cli/cmd/entire/cli/summarize"
21		"github.com/entireio/cli/cmd/entire/cli/summarytui"
22		"github.com/entireio/cli/cmd/entire/cli/termstyle"
23		"github.com/spf13/cobra"
24	)
25	
26	type summaryOptions struct {
27		Last             int
28		Agent            string
29		Branch           string
30		Me               bool
31		OutputJSON       bool
32		CheckpointPrefix string
33	}
34	
35	const (
36		defaultSummarySessionLimit = 10
37		maxSummaryRecentSessions   = 200
38	)
39	
40	type summarySessionView struct {
41		CheckpointID string               `json:"checkpoint_id"`
42		SessionID    string               `json:"session_id"`
43		Agent        string               `json:"agent"`
44		Model        string               `json:"model,omitempty"`
45		Branch       string               `json:"branch,omitempty"`
46		OwnerID      string               `json:"owner_id,omitempty"`
47		CreatedAt    string               `json:"created_at"`
48		Tokens       int                  `json:"tokens"`
49		Turns        int                  `json:"turns"`
50		HasSummary   bool                 `json:"has_summary"`
51		HasFacets    bool                 `json:"has_facets"`
52		Summary      summaryDetailView    `json:"summary"`
53		Facets       facets.SessionFacets `json:"facets"`
54	}
55	
56	type summaryDetailView struct {
57		Intent                  string                   `json:"intent,omitempty"`
58		Outcome                 string                   `json:"outcome,omitempty"`
59		Friction                []string                 `json:"friction,omitempty"`
60		Learnings               []insightsdb.LearningRow `json:"learnings,omitempty"`
61		ImplementationRationale []string                 `json:"implementation_rationale,omitempty"`
62		Tradeoffs               []string                 `json:"tradeoffs,omitempty"`
63		CodebasePatterns        []string                 `json:"codebase_patterns,omitempty"`
64	}
65	
66	var runSummaryTUI = summarytui.RunWithCurrentBranch //nolint:gochecknoglobals // injectable for testing
67	
68	// loadRepoSessions returns the most recent sessions whose checkpoints are reachable
69	// from the default branch. Returns nil silently on any error.
70	func loadRepoSessions(ctx context.Context) []insightsdb.SessionRow {
71		repoCheckpoints := buildRepoCheckpointSet(ctx)
72		if len(repoCheckpoints) == 0 {
73			return nil
74		}
75		worktreeRoot, err := paths.WorktreeRoot(ctx)
76		if err != nil {
77			return nil
78		}
79		idb, err := insightsdb.Open(filepath.Join(worktreeRoot, paths.EntireDir, "insights.db"))
80		if err != nil {
81			return nil
82		}
83		defer func() { _ = idb.Close() }()
84	
85		ids := make([]string, 0, len(repoCheckpoints))
86		for id := range repoCheckpoints {
87			ids = append(ids, id)
88		}
89		rows, err := idb.QueryByCheckpointIDs(ctx, ids, maxSummaryRecentSessions)
90		if err != nil {
91			return nil
92		}
93		return rows
94	}
95	
96	var summaryRefreshCacheIfStale = refreshCacheIfStale
97	
98	func newSummaryCmd() *cobra.Command {
99		opts := summaryOptions{Last: defaultSummarySessionLimit}
100	
101		cmd := &cobra.Command{
102			Use:   "summary [checkpoint-id]",
103			Short: "Browse source sessions with summaries and facets",
104			Args:  cobra.MaximumNArgs(1),
105			RunE: func(cmd *cobra.Command, args []string) error {
106				ctx := cmd.Context()
107				w := cmd.OutOrStdout()
108	
109				if checkDisabledGuard(ctx, w) {
110					return nil
111				}
112	
113				if !settings.IsSummarizeEnabled(ctx) {
114					fmt.Fprintln(w, "Summarization is required for summary browsing. Enable it in .entire/settings.json:")
115					fmt.Fprintln(w, `  { "strategy_options": { "summarize": { "enabled": true } } }`)
116					return nil
117				}
118	
119				if len(args) > 0 {
120					opts.CheckpointPrefix = args[0]
121				}
122	
123				return runSummary(ctx, w, opts)
124			},
125		}
126	
127		cmd.Flags().IntVar(&opts.Last, "last", opts.Last, "number of recent sessions to browse")
128		cmd.Flags().StringVar(&opts.Agent, "agent", "", "filter by agent name")
129		cmd.Flags().StringVar(&opts.Branch, "branch", "", "filter by branch")
130		cmd.Flags().BoolVar(&opts.Me, "me", false, "show only sessions for the active GitHub user")
131		cmd.Flags().BoolVar(&opts.OutputJSON, "json", false, "output sessions as JSON instead of launching the browser")
132		return cmd
133	}
134	
135	func runSummary(ctx context.Context, w io.Writer, opts summaryOptions) error {
136		rows, err := loadSummarySessions(ctx, opts)
137		if err != nil {
138			return err
139		}
140	
141		if opts.OutputJSON {
142			return renderSummaryJSON(w, rows)
143		}
144	
145		if IsAccessibleMode() {
146			renderSummaryText(w, rows)
147			return nil
148		}
149	
150		currentBranch := ""
151		if branch, err := GetCurrentBranch(ctx); err == nil {
152			currentBranch = branch
153		}
154	
155		// Load repo-scoped rows: the most recent sessions whose checkpoints
156		// are reachable from the default branch (independent view from current-branch rows).
157		repoRows := loadRepoSessions(ctx)
158	
159		return runSummaryTUI(ctx, rows, currentBranch, repoRows, generateForSession)
160	}
161	
162	func loadSummarySessions(ctx context.Context, opts summaryOptions) ([]insightsdb.SessionRow, error) {
163		worktreeRoot, err := paths.WorktreeRoot(ctx)
164		if err != nil {
165			return nil, fmt.Errorf("not in a git repository: %w", err)
166		}
167	
168		idb, err := insightsdb.Open(filepath.Join(worktreeRoot, paths.EntireDir, "insights.db"))
169		if err != nil {
170			return nil, fmt.Errorf("open insights cache: %w", err)
171		}
172		defer func() { _ = idb.Close() }()
173	
174		outputLimit := normalizedSummarySessionLimit(opts.Last)
175	
176		// Checkpoint prefix lookup: skip normal loading, query directly by prefix.
177		if opts.CheckpointPrefix != "" {
178			rows, err := idb.QueryByCheckpointPrefix(ctx, opts.CheckpointPrefix)
179			if err != nil {
180				return nil, fmt.Errorf("query by checkpoint: %w", err)
181			}
182			if len(rows) == 0 {
183				// Try refreshing cache in case the checkpoint hasn't been indexed yet.
184				if err := summaryRefreshCacheIfStale(ctx, idb); err != nil {
185					return nil, fmt.Errorf("refresh insights cache: %w", err)
186				}
187				rows, err = idb.QueryByCheckpointPrefix(ctx, opts.CheckpointPrefix)
188				if err != nil {
189					return nil, fmt.Errorf("query by checkpoint after refresh: %w", err)
190				}
191			}
192			if len(rows) == 0 {
193				return nil, fmt.Errorf("checkpoint not found: %s", opts.CheckpointPrefix)
194			}
195			return rows, nil
196		}
197	
198		rows, err := idb.QueryLastNSessions(ctx, maxSummaryRecentSessions)
199		if err != nil {
200			return nil, fmt.Errorf("query sessions: %w", err)
201		}
202		if len(rows) == 0 {
203			// First-run fallback: populate the cache if we have nothing local yet.
204			if err := summaryRefreshCacheIfStale(ctx, idb); err != nil {
205				return nil, fmt.Errorf("refresh insights cache: %w", err)
206			}
207			rows, err = idb.QueryLastNSessions(ctx, maxSummaryRecentSessions)
208			if err != nil {
209				return nil, fmt.Errorf("query sessions after refresh: %w", err)
210			}
211		}
212	
213		ownerID := ""
214		if opts.Me {
215			ownerID, err = githubidentity.ResolveUsername(ctx)
216			if err != nil {
217				return nil, fmt.Errorf("resolve github username: %w", err)
218			}
219		}
220	
221		hasCLIFilters := opts.Agent != "" || opts.Branch != "" || ownerID != ""
222	
223		filtered := make([]insightsdb.SessionRow, 0, len(rows))
224		for _, row := range rows {
225			if opts.Agent != "" && !strings.EqualFold(strings.TrimSpace(row.Agent), strings.TrimSpace(opts.Agent)) {
226				continue
227			}
228			if opts.Branch != "" && !strings.EqualFold(strings.TrimSpace(row.Branch), strings.TrimSpace(opts.Branch)) {
229				continue
230			}
231			if ownerID != "" && !strings.EqualFold(strings.TrimSpace(row.OwnerID), ownerID) {
232				continue
233			}
234			filtered = append(filtered, row)
235			// Only cap results when CLI filters or JSON output are in use.
236			// The TUI has its own branch filter, so it needs the full result set.
237			if hasCLIFilters && len(filtered) == outputLimit {
238				break
239			}
240		}
241	
242		return filtered, nil
243	}
244	
245	func normalizedSummarySessionLimit(last int) int {
246		if last <= 0 {
247			return defaultSummarySessionLimit
248		}
249		return min(last, maxSummaryRecentSessions)
250	}
251	
252	//nolint:musttag // nested external structs are part of the intended JSON payload
253	func renderSummaryJSON(w io.Writer, rows []insightsdb.SessionRow) error {
254		views := make([]summarySessionView, 0, len(rows))
255		for _, row := range rows {
256			views = append(views, summarySessionToView(row))
257		}
258	
259		enc := json.NewEncoder(w)
260		enc.SetIndent("", "  ")
261		if err := enc.Encode(views); err != nil {
262			return fmt.Errorf("encode summary sessions: %w", err)
263		}
264		return nil
265	}
266	
267	func renderSummaryText(w io.Writer, rows []insightsdb.SessionRow) {
268		s := termstyle.New(w)
269		fmt.Fprintln(w, s.Render(s.Bold, "Session Summary"))
270		if len(rows) == 0 {
271			fmt.Fprintln(w, "No sessions found.")
272			return
273		}
274	
275		for _, row := range rows {
276			fmt.Fprintf(w, "\n%s  %s  %s\n", row.CreatedAt.Format("2006-01-02 15:04"), row.Agent, row.SessionID)
277			if row.OwnerID != "" || row.OwnerName != "" || row.OwnerEmail != "" {
278				fmt.Fprintf(w, "Author: %s\n", fallbackText(row.OwnerID, "(unknown)"))
279				if row.OwnerName != "" {
280					fmt.Fprintf(w, "Author Name: %s\n", row.OwnerName)
281				}
282				if row.OwnerEmail != "" {
283					fmt.Fprintf(w, "Author Email: %s\n", row.OwnerEmail)
284				}
285			}
286			if row.Branch != "" {
287				fmt.Fprintf(w, "Branch: %s\n", row.Branch)
288			}
289			fmt.Fprintf(w, "Checkpoint: %s\n", row.CheckpointID)
290			fmt.Fprintf(w, "Summary: %s  Facets: %s\n", yesNo(row.HasSummary), yesNo(row.HasFacets))
291	
292			if row.HasSummary {
293				fmt.Fprintln(w, "Intent:")
294				fmt.Fprintf(w, "  %s\n", fallbackText(row.Intent, "No summary cached"))
295				fmt.Fprintln(w, "Outcome:")
296				fmt.Fprintf(w, "  %s\n", fallbackText(row.Outcome, "No summary cached"))
297				renderStringListSection(w, "Friction", row.Friction, "No friction recorded")
298				renderLearningSection(w, row.Learnings)
299				renderStringListSection(w, "Implementation Rationale", row.ImplementationRationale, "No implementation rationale recorded")
300				renderStringListSection(w, "Tradeoffs", row.Tradeoffs, "No tradeoffs recorded")
301				renderStringListSection(w, "Codebase Patterns", row.CodebasePatterns, "No codebase patterns recorded")
302			} else {
303				fmt.Fprintln(w, "No summary cached")
304			}
305	
306			renderFacetSections(w, row.Facets, row.HasFacets)
307		}
308	}
309	
310	func renderLearningSection(w io.Writer, learnings []insightsdb.LearningRow) {
311		if len(learnings) == 0 {
312			fmt.Fprintln(w, "Learnings:")
313			fmt.Fprintln(w, "  No learnings recorded")
314			return
315		}
316	
317		fmt.Fprintln(w, "Learnings:")
318		for _, learning := range learnings {
319			if learning.Path != "" {
320				fmt.Fprintf(w, "  - [%s] %s (%s)\n", learning.Scope, learning.Finding, learning.Path)
321				continue
322			}
323			fmt.Fprintf(w, "  - [%s] %s\n", learning.Scope, learning.Finding)
324		}
325	}
326	
327	func renderFacetSections(w io.Writer, data facets.SessionFacets, hasFacets bool) {
328		if !hasFacets {
329			fmt.Fprintln(w, "No facets cached")
330			return
331		}
332	
333		fmt.Fprintln(w, "Repeated Instructions:")
334		if len(data.RepeatedUserInstructions) == 0 {
335			fmt.Fprintln(w, "  None")
336		} else {
337			for _, item := range data.RepeatedUserInstructions {
338				fmt.Fprintf(w, "  - %s\n", item.Instruction)
339			}
340		}
341	
342		fmt.Fprintln(w, "Missing Context:")
343		if len(data.MissingContext) == 0 {
344			fmt.Fprintln(w, "  None")
345		} else {
346			for _, item := range data.MissingContext {
347				fmt.Fprintf(w, "  - %s\n", item.Item)
348			}
349		}
350	
351		fmt.Fprintln(w, "Review-Derived Rules:")
352		if len(data.ReviewDerivedRules) == 0 {
353			fmt.Fprintln(w, "  None")
354		} else {
355			for _, item := range data.ReviewDerivedRules {
356				fmt.Fprintf(w, "  - %s\n", item.Rule)
357			}
358		}
359	
360		fmt.Fprintln(w, "Failure Loops:")
361		if len(data.FailureLoops) == 0 {
362			fmt.Fprintln(w, "  None")
363		} else {
364			for _, item := range data.FailureLoops {
365				fmt.Fprintf(w, "  - %s (%d)\n", item.Description, item.Count)
366			}
367		}
368	
369		fmt.Fprintln(w, "Skill Signals:")
370		if len(data.SkillSignals) == 0 {
371			fmt.Fprintln(w, "  None")
372		} else {
373			for _, item := range data.SkillSignals {
374				fmt.Fprintf(w, "  - %s\n", item.SkillName)
375			}
376		}
377	
378		fmt.Fprintln(w, "Repo Gotchas:")
379		if len(data.RepoGotchas) == 0 {
380			fmt.Fprintln(w, "  None")
381		} else {
382			for _, item := range data.RepoGotchas {
383				fmt.Fprintf(w, "  - %s\n", item)
384			}
385		}
386	
387		fmt.Fprintln(w, "Workflow Gaps:")
388		if len(data.WorkflowGaps) == 0 {
389			fmt.Fprintln(w, "  None")
390		} else {
391			for _, item := range data.WorkflowGaps {
392				fmt.Fprintf(w, "  - %s\n", item)
393			}
394		}
395	}
396	
397	func renderStringListSection(w io.Writer, title string, items []string, empty string) {
398		fmt.Fprintf(w, "%s:\n", title)
399		if len(items) == 0 {
400			fmt.Fprintf(w, "  %s\n", empty)
401			return
402		}
403		for _, item := range items {
404			fmt.Fprintf(w, "  - %s\n", item)
405		}
406	}
407	
408	func summarySessionToView(row insightsdb.SessionRow) summarySessionView {
409		return summarySessionView{
410			CheckpointID: row.CheckpointID,
411			SessionID:    row.SessionID,
412			Agent:        row.Agent,
413			Model:        row.Model,
414			Branch:       row.Branch,
415			OwnerID:      row.OwnerID,
416			CreatedAt:    row.CreatedAt.Format("2006-01-02T15:04:05Z07:00"),
417			Tokens:       row.TotalTokens,
418			Turns:        row.TurnCount,
419			HasSummary:   row.HasSummary,
420			HasFacets:    row.HasFacets,
421			Summary: summaryDetailView{
422				Intent:                  row.Intent,
423				Outcome:                 row.Outcome,
424				Friction:                row.Friction,
425				Learnings:               row.Learnings,
426				ImplementationRationale: row.ImplementationRationale,
427				Tradeoffs:               row.Tradeoffs,
428				CodebasePatterns:        row.CodebasePatterns,
429			},
430			Facets: row.Facets,
431		}
432	}
433	
434	func yesNo(v bool) string {
435		if v {
436			return "yes"
437		}
438		return "no"
439	}
440	
441	func fallbackText(value, fb string) string {
442		if strings.TrimSpace(value) == "" {
443			return fb
444		}
445		return value
446	}
447	
448	// buildRepoCheckpointSet returns the set of checkpoint IDs reachable from the
449	// default branch. Returns nil if the default branch can't be resolved (the TUI
450	// will treat nil as "repo filter unavailable" and show all sessions).
451	func buildRepoCheckpointSet(ctx context.Context) map[string]struct{} {
452		repo, err := openRepository(ctx)
453		if err != nil {
454			return nil
455		}
456		_, defaultBranchHash, err := resolveMemoryLoopDefaultBranch(repo)
457		if err != nil {
458			return nil
459		}
460		ids, err := listReachableCheckpointIDs(ctx, repo, defaultBranchHash)
461		if err != nil {
462			return nil
463		}
464		return ids
465	}
466	
467	// generateForSession generates summary and facets for a single session on demand.
468	// It opens its own database connection and checkpoint store.
469	func generateForSession(ctx context.Context, row insightsdb.SessionRow) (insightsdb.SessionRow, error) {
470		repo, err := openRepository(ctx)
471		if err != nil {
472			return row, fmt.Errorf("open repository: %w", err)
473		}
474		store := checkpoint.NewGitStore(repo)
475	
476		cpID, err := checkpointid.NewCheckpointID(row.CheckpointID)
477		if err != nil {
478			return row, fmt.Errorf("invalid checkpoint ID: %w", err)
479		}
480	
481		content, err := store.ReadSessionContent(ctx, cpID, row.SessionIndex)
482		if err != nil {
483			return row, fmt.Errorf("read session content: %w", err)
484		}
485		if len(content.Transcript) == 0 {
486			return row, fmt.Errorf("empty transcript for checkpoint %s", row.CheckpointID)
487		}
488	
489		condensed, err := summarize.BuildCondensedTranscriptFromBytes(content.Transcript, content.Metadata.Agent)
490		if err != nil {
491			return row, fmt.Errorf("condense transcript: %w", err)
492		}
493		if len(condensed) == 0 {
494			return row, fmt.Errorf("condensed transcript empty for checkpoint %s", row.CheckpointID)
495		}
496	
497		input := summarize.Input{
498			Transcript:   condensed,
499			FilesTouched: row.FilesTouched,
500		}
501	
502		// Generate summary.
503		gen := &summarize.ClaudeGenerator{}
504		summary, genErr := gen.Generate(ctx, input)
505		if genErr != nil {
506			logging.Debug(ctx, "generateForSession: summary generation failed",
507				"checkpoint_id", row.CheckpointID, "error", genErr)
508		}
509		if summary != nil {
510			content.Metadata.Summary = summary
511			row = metadataToSessionRow(row.CheckpointID, row.SessionIndex, &content.Metadata)
512		}
513	
514		// Extract facets.
515		formatted := summarize.FormatCondensedTranscript(input)
516		extractor := &facets.Extractor{Runner: &llmcli.Runner{}}
517		facetResult, _, extractErr := extractor.Extract(ctx, formatted)
518		if extractErr != nil {
519			logging.Debug(ctx, "generateForSession: facet extraction failed",
520				"checkpoint_id", row.CheckpointID, "error", extractErr)
521		}
522		if facetResult != nil {
523			row.Facets = *facetResult
524			row.HasFacets = true
525		}
526	
527		// Persist to database.
528		worktreeRoot, err := paths.WorktreeRoot(ctx)
529		if err != nil {
530			return row, fmt.Errorf("find worktree root: %w", err)
531		}
532		idb, err := insightsdb.Open(filepath.Join(worktreeRoot, paths.EntireDir, "insights.db"))
533		if err != nil {
534			return row, fmt.Errorf("open insights db: %w", err)
535		}
536		defer func() { _ = idb.Close() }()
537	
538		if row.HasSummary {
539			if updateErr := idb.UpdateSessionSummary(ctx, row); updateErr != nil {
540				return row, fmt.Errorf("save summary: %w", updateErr)
541			}
542		}
543		if row.HasFacets {
544			if updateErr := idb.UpdateSessionFacets(ctx, row); updateErr != nil {
545				return row, fmt.Errorf("save facets: %w", updateErr)
546			}
547		}
548	
549		// Return partial success even if one phase failed.
550		if genErr != nil && extractErr != nil {
551			return row, fmt.Errorf("summary: %w; facets: %w", genErr, extractErr)
552		}
553		return row, nil
554	}
