package cli

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	checkpointid "github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/facets"
	"github.com/entireio/cli/cmd/entire/cli/githubidentity"
	"github.com/entireio/cli/cmd/entire/cli/insightsdb"
	"github.com/entireio/cli/cmd/entire/cli/llmcli"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/settings"
	"github.com/entireio/cli/cmd/entire/cli/summarize"
	"github.com/entireio/cli/cmd/entire/cli/summarytui"
	"github.com/entireio/cli/cmd/entire/cli/termstyle"
	"github.com/spf13/cobra"
)

type summaryOptions struct {
	Last             int
	Agent            string
	Branch           string
	Me               bool
	OutputJSON       bool
	CheckpointPrefix string
}

const (
	defaultSummarySessionLimit = 10
	maxSummaryRecentSessions   = 200
)

type summarySessionView struct {
	CheckpointID string               `json:"checkpoint_id"`
	SessionID    string               `json:"session_id"`
	Agent        string               `json:"agent"`
	Model        string               `json:"model,omitempty"`
	Branch       string               `json:"branch,omitempty"`
	OwnerID      string               `json:"owner_id,omitempty"`
	CreatedAt    string               `json:"created_at"`
	Tokens       int                  `json:"tokens"`
	Turns        int                  `json:"turns"`
	HasSummary   bool                 `json:"has_summary"`
	HasFacets    bool                 `json:"has_facets"`
	Summary      summaryDetailView    `json:"summary"`
	Facets       facets.SessionFacets `json:"facets"`
}

type summaryDetailView struct {
	Intent                  string                   `json:"intent,omitempty"`
	Outcome                 string                   `json:"outcome,omitempty"`
	Friction                []string                 `json:"friction,omitempty"`
	Learnings               []insightsdb.LearningRow `json:"learnings,omitempty"`
	ImplementationRationale []string                 `json:"implementation_rationale,omitempty"`
	Tradeoffs               []string                 `json:"tradeoffs,omitempty"`
	CodebasePatterns        []string                 `json:"codebase_patterns,omitempty"`
}

var runSummaryTUI = summarytui.RunWithCurrentBranch //nolint:gochecknoglobals // injectable for testing

// loadRepoSessions returns the most recent sessions whose checkpoints are reachable
// from the default branch. Returns nil silently on any error.
func loadRepoSessions(ctx context.Context) []insightsdb.SessionRow {
	repoCheckpoints := buildRepoCheckpointSet(ctx)
	if len(repoCheckpoints) == 0 {
		return nil
	}
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil
	}
	idb, err := insightsdb.Open(filepath.Join(worktreeRoot, paths.EntireDir, "insights.db"))
	if err != nil {
		return nil
	}
	defer func() { _ = idb.Close() }()

	ids := make([]string, 0, len(repoCheckpoints))
	for id := range repoCheckpoints {
		ids = append(ids, id)
	}
	rows, err := idb.QueryByCheckpointIDs(ctx, ids, maxSummaryRecentSessions)
	if err != nil {
		return nil
	}
	return rows
}

var summaryRefreshCacheIfStale = refreshCacheIfStale

func newSummaryCmd() *cobra.Command {
	opts := summaryOptions{Last: defaultSummarySessionLimit}

	cmd := &cobra.Command{
		Use:   "summary [checkpoint-id]",
		Short: "Browse source sessions with summaries and facets",
		Args:  cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			w := cmd.OutOrStdout()

			if checkDisabledGuard(ctx, w) {
				return nil
			}

			if !settings.IsSummarizeEnabled(ctx) {
				fmt.Fprintln(w, "Summarization is required for summary browsing. Enable it in .entire/settings.json:")
				fmt.Fprintln(w, `  { "strategy_options": { "summarize": { "enabled": true } } }`)
				return nil
			}

			if len(args) > 0 {
				opts.CheckpointPrefix = args[0]
			}

			return runSummary(ctx, w, opts)
		},
	}

	cmd.Flags().IntVar(&opts.Last, "last", opts.Last, "number of recent sessions to browse")
	cmd.Flags().StringVar(&opts.Agent, "agent", "", "filter by agent name")
	cmd.Flags().StringVar(&opts.Branch, "branch", "", "filter by branch")
	cmd.Flags().BoolVar(&opts.Me, "me", false, "show only sessions for the active GitHub user")
	cmd.Flags().BoolVar(&opts.OutputJSON, "json", false, "output sessions as JSON instead of launching the browser")
	return cmd
}

func runSummary(ctx context.Context, w io.Writer, opts summaryOptions) error {
	rows, err := loadSummarySessions(ctx, opts)
	if err != nil {
		return err
	}

	if opts.OutputJSON {
		return renderSummaryJSON(w, rows)
	}

	if IsAccessibleMode() {
		renderSummaryText(w, rows)
		return nil
	}

	currentBranch := ""
	if branch, err := GetCurrentBranch(ctx); err == nil {
		currentBranch = branch
	}

	// Load repo-scoped rows: the most recent sessions whose checkpoints
	// are reachable from the default branch (independent view from current-branch rows).
	repoRows := loadRepoSessions(ctx)

	return runSummaryTUI(ctx, rows, currentBranch, repoRows, generateForSession)
}

func loadSummarySessions(ctx context.Context, opts summaryOptions) ([]insightsdb.SessionRow, error) {
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil, fmt.Errorf("not in a git repository: %w", err)
	}

	idb, err := insightsdb.Open(filepath.Join(worktreeRoot, paths.EntireDir, "insights.db"))
	if err != nil {
		return nil, fmt.Errorf("open insights cache: %w", err)
	}
	defer func() { _ = idb.Close() }()

	outputLimit := normalizedSummarySessionLimit(opts.Last)

	// Checkpoint prefix lookup: skip normal loading, query directly by prefix.
	if opts.CheckpointPrefix != "" {
		rows, err := idb.QueryByCheckpointPrefix(ctx, opts.CheckpointPrefix)
		if err != nil {
			return nil, fmt.Errorf("query by checkpoint: %w", err)
		}
		if len(rows) == 0 {
			// Try refreshing cache in case the checkpoint hasn't been indexed yet.
			if err := summaryRefreshCacheIfStale(ctx, idb); err != nil {
				return nil, fmt.Errorf("refresh insights cache: %w", err)
			}
			rows, err = idb.QueryByCheckpointPrefix(ctx, opts.CheckpointPrefix)
			if err != nil {
				return nil, fmt.Errorf("query by checkpoint after refresh: %w", err)
			}
		}
		if len(rows) == 0 {
			return nil, fmt.Errorf("checkpoint not found: %s", opts.CheckpointPrefix)
		}
		return rows, nil
	}

	rows, err := idb.QueryLastNSessions(ctx, maxSummaryRecentSessions)
	if err != nil {
		return nil, fmt.Errorf("query sessions: %w", err)
	}
	if len(rows) == 0 {
		// First-run fallback: populate the cache if we have nothing local yet.
		if err := summaryRefreshCacheIfStale(ctx, idb); err != nil {
			return nil, fmt.Errorf("refresh insights cache: %w", err)
		}
		rows, err = idb.QueryLastNSessions(ctx, maxSummaryRecentSessions)
		if err != nil {
			return nil, fmt.Errorf("query sessions after refresh: %w", err)
		}
	}

	ownerID := ""
	if opts.Me {
		ownerID, err = githubidentity.ResolveUsername(ctx)
		if err != nil {
			return nil, fmt.Errorf("resolve github username: %w", err)
		}
	}

	hasCLIFilters := opts.Agent != "" || opts.Branch != "" || ownerID != ""

	filtered := make([]insightsdb.SessionRow, 0, len(rows))
	for _, row := range rows {
		if opts.Agent != "" && !strings.EqualFold(strings.TrimSpace(row.Agent), strings.TrimSpace(opts.Agent)) {
			continue
		}
		if opts.Branch != "" && !strings.EqualFold(strings.TrimSpace(row.Branch), strings.TrimSpace(opts.Branch)) {
			continue
		}
		if ownerID != "" && !strings.EqualFold(strings.TrimSpace(row.OwnerID), ownerID) {
			continue
		}
		filtered = append(filtered, row)
		// Only cap results when CLI filters or JSON output are in use.
		// The TUI has its own branch filter, so it needs the full result set.
		if hasCLIFilters && len(filtered) == outputLimit {
			break
		}
	}

	return filtered, nil
}

func normalizedSummarySessionLimit(last int) int {
	if last <= 0 {
		return defaultSummarySessionLimit
	}
	return min(last, maxSummaryRecentSessions)
}

//nolint:musttag // nested external structs are part of the intended JSON payload
func renderSummaryJSON(w io.Writer, rows []insightsdb.SessionRow) error {
	views := make([]summarySessionView, 0, len(rows))
	for _, row := range rows {
		views = append(views, summarySessionToView(row))
	}

	enc := json.NewEncoder(w)
	enc.SetIndent("", "  ")
	if err := enc.Encode(views); err != nil {
		return fmt.Errorf("encode summary sessions: %w", err)
	}
	return nil
}

func renderSummaryText(w io.Writer, rows []insightsdb.SessionRow) {
	s := termstyle.New(w)
	fmt.Fprintln(w, s.Render(s.Bold, "Session Summary"))
	if len(rows) == 0 {
		fmt.Fprintln(w, "No sessions found.")
		return
	}

	for _, row := range rows {
		fmt.Fprintf(w, "\n%s  %s  %s\n", row.CreatedAt.Format("2006-01-02 15:04"), row.Agent, row.SessionID)
		if row.OwnerID != "" || row.OwnerName != "" || row.OwnerEmail != "" {
			fmt.Fprintf(w, "Author: %s\n", fallbackText(row.OwnerID, "(unknown)"))
			if row.OwnerName != "" {
				fmt.Fprintf(w, "Author Name: %s\n", row.OwnerName)
			}
			if row.OwnerEmail != "" {
				fmt.Fprintf(w, "Author Email: %s\n", row.OwnerEmail)
			}
		}
		if row.Branch != "" {
			fmt.Fprintf(w, "Branch: %s\n", row.Branch)
		}
		fmt.Fprintf(w, "Checkpoint: %s\n", row.CheckpointID)
		fmt.Fprintf(w, "Summary: %s  Facets: %s\n", yesNo(row.HasSummary), yesNo(row.HasFacets))

		if row.HasSummary {
			fmt.Fprintln(w, "Intent:")
			fmt.Fprintf(w, "  %s\n", fallbackText(row.Intent, "No summary cached"))
			fmt.Fprintln(w, "Outcome:")
			fmt.Fprintf(w, "  %s\n", fallbackText(row.Outcome, "No summary cached"))
			renderStringListSection(w, "Friction", row.Friction, "No friction recorded")
			renderLearningSection(w, row.Learnings)
			renderStringListSection(w, "Implementation Rationale", row.ImplementationRationale, "No implementation rationale recorded")
			renderStringListSection(w, "Tradeoffs", row.Tradeoffs, "No tradeoffs recorded")
			renderStringListSection(w, "Codebase Patterns", row.CodebasePatterns, "No codebase patterns recorded")
		} else {
			fmt.Fprintln(w, "No summary cached")
		}

		renderFacetSections(w, row.Facets, row.HasFacets)
	}
}

func renderLearningSection(w io.Writer, learnings []insightsdb.LearningRow) {
	if len(learnings) == 0 {
		fmt.Fprintln(w, "Learnings:")
		fmt.Fprintln(w, "  No learnings recorded")
		return
	}

	fmt.Fprintln(w, "Learnings:")
	for _, learning := range learnings {
		if learning.Path != "" {
			fmt.Fprintf(w, "  - [%s] %s (%s)\n", learning.Scope, learning.Finding, learning.Path)
			continue
		}
		fmt.Fprintf(w, "  - [%s] %s\n", learning.Scope, learning.Finding)
	}
}

func renderFacetSections(w io.Writer, data facets.SessionFacets, hasFacets bool) {
	if !hasFacets {
		fmt.Fprintln(w, "No facets cached")
		return
	}

	fmt.Fprintln(w, "Repeated Instructions:")
	if len(data.RepeatedUserInstructions) == 0 {
		fmt.Fprintln(w, "  None")
	} else {
		for _, item := range data.RepeatedUserInstructions {
			fmt.Fprintf(w, "  - %s\n", item.Instruction)
		}
	}

	fmt.Fprintln(w, "Missing Context:")
	if len(data.MissingContext) == 0 {
		fmt.Fprintln(w, "  None")
	} else {
		for _, item := range data.MissingContext {
			fmt.Fprintf(w, "  - %s\n", item.Item)
		}
	}

	fmt.Fprintln(w, "Review-Derived Rules:")
	if len(data.ReviewDerivedRules) == 0 {
		fmt.Fprintln(w, "  None")
	} else {
		for _, item := range data.ReviewDerivedRules {
			fmt.Fprintf(w, "  - %s\n", item.Rule)
		}
	}

	fmt.Fprintln(w, "Failure Loops:")
	if len(data.FailureLoops) == 0 {
		fmt.Fprintln(w, "  None")
	} else {
		for _, item := range data.FailureLoops {
			fmt.Fprintf(w, "  - %s (%d)\n", item.Description, item.Count)
		}
	}

	fmt.Fprintln(w, "Skill Signals:")
	if len(data.SkillSignals) == 0 {
		fmt.Fprintln(w, "  None")
	} else {
		for _, item := range data.SkillSignals {
			fmt.Fprintf(w, "  - %s\n", item.SkillName)
		}
	}

	fmt.Fprintln(w, "Repo Gotchas:")
	if len(data.RepoGotchas) == 0 {
		fmt.Fprintln(w, "  None")
	} else {
		for _, item := range data.RepoGotchas {
			fmt.Fprintf(w, "  - %s\n", item)
		}
	}

	fmt.Fprintln(w, "Workflow Gaps:")
	if len(data.WorkflowGaps) == 0 {
		fmt.Fprintln(w, "  None")
	} else {
		for _, item := range data.WorkflowGaps {
			fmt.Fprintf(w, "  - %s\n", item)
		}
	}
}

func renderStringListSection(w io.Writer, title string, items []string, empty string) {
	fmt.Fprintf(w, "%s:\n", title)
	if len(items) == 0 {
		fmt.Fprintf(w, "  %s\n", empty)
		return
	}
	for _, item := range items {
		fmt.Fprintf(w, "  - %s\n", item)
	}
}

func summarySessionToView(row insightsdb.SessionRow) summarySessionView {
	return summarySessionView{
		CheckpointID: row.CheckpointID,
		SessionID:    row.SessionID,
		Agent:        row.Agent,
		Model:        row.Model,
		Branch:       row.Branch,
		OwnerID:      row.OwnerID,
		CreatedAt:    row.CreatedAt.Format("2006-01-02T15:04:05Z07:00"),
		Tokens:       row.TotalTokens,
		Turns:        row.TurnCount,
		HasSummary:   row.HasSummary,
		HasFacets:    row.HasFacets,
		Summary: summaryDetailView{
			Intent:                  row.Intent,
			Outcome:                 row.Outcome,
			Friction:                row.Friction,
			Learnings:               row.Learnings,
			ImplementationRationale: row.ImplementationRationale,
			Tradeoffs:               row.Tradeoffs,
			CodebasePatterns:        row.CodebasePatterns,
		},
		Facets: row.Facets,
	}
}

func yesNo(v bool) string {
	if v {
		return "yes"
	}
	return "no"
}

func fallbackText(value, fb string) string {
	if strings.TrimSpace(value) == "" {
		return fb
	}
	return value
}

// buildRepoCheckpointSet returns the set of checkpoint IDs reachable from the
// default branch. Returns nil if the default branch can't be resolved (the TUI
// will treat nil as "repo filter unavailable" and show all sessions).
func buildRepoCheckpointSet(ctx context.Context) map[string]struct{} {
	repo, err := openRepository(ctx)
	if err != nil {
		return nil
	}
	_, defaultBranchHash, err := resolveMemoryLoopDefaultBranch(repo)
	if err != nil {
		return nil
	}
	ids, err := listReachableCheckpointIDs(ctx, repo, defaultBranchHash)
	if err != nil {
		return nil
	}
	return ids
}

// generateForSession generates summary and facets for a single session on demand.
// It opens its own database connection and checkpoint store.
func generateForSession(ctx context.Context, row insightsdb.SessionRow) (insightsdb.SessionRow, error) {
	repo, err := openRepository(ctx)
	if err != nil {
		return row, fmt.Errorf("open repository: %w", err)
	}
	store := checkpoint.NewGitStore(repo)

	cpID, err := checkpointid.NewCheckpointID(row.CheckpointID)
	if err != nil {
		return row, fmt.Errorf("invalid checkpoint ID: %w", err)
	}

	content, err := store.ReadSessionContent(ctx, cpID, row.SessionIndex)
	if err != nil {
		return row, fmt.Errorf("read session content: %w", err)
	}
	if len(content.Transcript) == 0 {
		return row, fmt.Errorf("empty transcript for checkpoint %s", row.CheckpointID)
	}

	condensed, err := summarize.BuildCondensedTranscriptFromBytes(content.Transcript, content.Metadata.Agent)
	if err != nil {
		return row, fmt.Errorf("condense transcript: %w", err)
	}
	if len(condensed) == 0 {
		return row, fmt.Errorf("condensed transcript empty for checkpoint %s", row.CheckpointID)
	}

	input := summarize.Input{
		Transcript:   condensed,
		FilesTouched: row.FilesTouched,
	}

	// Generate summary.
	gen := &summarize.ClaudeGenerator{}
	summary, genErr := gen.Generate(ctx, input)
	if genErr != nil {
		logging.Debug(ctx, "generateForSession: summary generation failed",
			"checkpoint_id", row.CheckpointID, "error", genErr)
	}
	if summary != nil {
		content.Metadata.Summary = summary
		row = metadataToSessionRow(row.CheckpointID, row.SessionIndex, &content.Metadata)
	}

	// Extract facets.
	formatted := summarize.FormatCondensedTranscript(input)
	extractor := &facets.Extractor{Runner: &llmcli.Runner{}}
	facetResult, _, extractErr := extractor.Extract(ctx, formatted)
	if extractErr != nil {
		logging.Debug(ctx, "generateForSession: facet extraction failed",
			"checkpoint_id", row.CheckpointID, "error", extractErr)
	}
	if facetResult != nil {
		row.Facets = *facetResult
		row.HasFacets = true
	}

	// Persist to database.
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return row, fmt.Errorf("find worktree root: %w", err)
	}
	idb, err := insightsdb.Open(filepath.Join(worktreeRoot, paths.EntireDir, "insights.db"))
	if err != nil {
		return row, fmt.Errorf("open insights db: %w", err)
	}
	defer func() { _ = idb.Close() }()

	if row.HasSummary {
		if updateErr := idb.UpdateSessionSummary(ctx, row); updateErr != nil {
			return row, fmt.Errorf("save summary: %w", updateErr)
		}
	}
	if row.HasFacets {
		if updateErr := idb.UpdateSessionFacets(ctx, row); updateErr != nil {
			return row, fmt.Errorf("save facets: %w", updateErr)
		}
	}

	// Return partial success even if one phase failed.
	if genErr != nil && extractErr != nil {
		return row, fmt.Errorf("summary: %w; facets: %w", genErr, extractErr)
	}
	return row, nil
}

package summarytui

import (
	"context"
	"fmt"
	"os"
	"strings"
	"time"

	"github.com/charmbracelet/bubbles/key"
	"github.com/charmbracelet/bubbles/paginator"
	"github.com/charmbracelet/bubbles/viewport"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"github.com/entireio/cli/cmd/entire/cli/insightsdb"
)

const defaultPageSize = 10

// Chrome: filter bar (1) + gap (1) + separator (1) + list header (1) + separator (1) + status bar (1) + padding (1) = 7
const verticalChrome = 7

// GenerateFunc generates summary and facets for a single session on demand.
type GenerateFunc func(ctx context.Context, row insightsdb.SessionRow) (insightsdb.SessionRow, error)

type branchFilter int

const (
	filterCurrentBranch branchFilter = iota // current working branch
	filterRepo                              // all branches in this repo
)

type timeFilter int

const (
	timeFilter24h timeFilter = iota
	timeFilter7d
	timeFilter30d
	timeFilterAll
)

//nolint:recvcheck // bubbletea pattern: value receiver for interface, pointer receivers for mutation helpers
type rootModel struct {
	ctx           context.Context
	branchRows    []insightsdb.SessionRow // rows for "current branch" view
	repoRows      []insightsdb.SessionRow // rows for "repo" view
	filteredRows  []insightsdb.SessionRow
	currentBranch string
	branchFilter  branchFilter
	timeFilter    timeFilter
	cursor        int
	paginator     paginator.Model
	pageSize      int
	detailVP      viewport.Model
	width         int
	height        int
	styles        styles
	generateFn    GenerateFunc
	generating    bool
	genStatus     string // status message for generate operation
	accessible    bool   // accessible mode fallback
}

type generateDoneMsg struct {
	row insightsdb.SessionRow
}

type generateErrMsg struct {
	err error
}

func Run(ctx context.Context, rows []insightsdb.SessionRow) error {
	return RunWithCurrentBranch(ctx, rows, "", nil, nil)
}

func RunWithCurrentBranch(_ context.Context, rows []insightsdb.SessionRow, currentBranch string, repoRows []insightsdb.SessionRow, generateFn GenerateFunc) error {
	p := tea.NewProgram(newRootModel(rows, currentBranch, repoRows, generateFn), tea.WithAltScreen())
	_, err := p.Run()
	if err != nil {
		return fmt.Errorf("run summary TUI: %w", err)
	}
	return nil
}

func newRootModel(rows []insightsdb.SessionRow, currentBranch string, repoRows []insightsdb.SessionRow, generateFn GenerateFunc) rootModel {
	s := newStyles()
	p := paginator.New()
	p.PerPage = defaultPageSize

	accessible := os.Getenv("ACCESSIBLE") != ""

	vp := viewport.New(60, 20)
	vp.MouseWheelEnabled = false

	m := rootModel{
		ctx:           context.Background(),
		branchRows:    append([]insightsdb.SessionRow(nil), rows...),
		repoRows:      append([]insightsdb.SessionRow(nil), repoRows...),
		currentBranch: currentBranch,
		branchFilter:  filterCurrentBranch,
		timeFilter:    timeFilterAll,
		paginator:     p,
		pageSize:      defaultPageSize,
		styles:        s,
		width:         100,
		height:        30,
		detailVP:      vp,
		generateFn:    generateFn,
		accessible:    accessible,
	}
	m.rebuildFilteredRows()
	m.updateDetailViewport()
	return m
}

func (m rootModel) Init() tea.Cmd {
	return nil
}

//nolint:cyclop,ireturn // required by bubbletea Model interface; state machine has inherent branching
func (m rootModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.resize(msg.Width, msg.Height)
		return m, nil

	case tea.KeyMsg:
		return m.updateKeys(msg)

	case generateDoneMsg:
		m.generating = false
		m.genStatus = "Generated"
		m.updateRowData(msg.row)
		m.updateDetailViewport()
		return m, nil

	case generateErrMsg:
		m.generating = false
		m.genStatus = "Error: " + msg.err.Error()
		return m, nil
	}

	return m, nil
}

//nolint:cyclop,ireturn // required by bubbletea pattern
func (m rootModel) updateKeys(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch {
	case key.Matches(msg, keys.quit):
		return m, tea.Quit
	case key.Matches(msg, keys.cycleTimeFilter):
		m.cycleTime()
		return m, nil
	case key.Matches(msg, keys.cycleBranchFilter):
		m.cycleBranch()
		return m, nil
	case key.Matches(msg, keys.cursorDown):
		m.moveCursor(1)
		return m, nil
	case key.Matches(msg, keys.cursorUp):
		m.moveCursor(-1)
		return m, nil
	case key.Matches(msg, keys.nextPage):
		m.nextPage()
		return m, nil
	case key.Matches(msg, keys.prevPage):
		m.prevPage()
		return m, nil
	case key.Matches(msg, keys.generate):
		return m.handleGenerate()
	}

	//nolint:exhaustive // only Ctrl+C needs special handling here
	switch msg.Type {
	case tea.KeyCtrlC:
		return m, tea.Quit
	default:
	}

	// Scroll detail viewport
	var cmd tea.Cmd
	m.detailVP, cmd = m.detailVP.Update(msg)
	return m, cmd
}

func (m rootModel) handleGenerate() (tea.Model, tea.Cmd) {
	if m.generateFn == nil || m.generating {
		return m, nil
	}
	row := m.selectedRow()
	if row == nil {
		return m, nil
	}
	m.generating = true
	m.genStatus = "Generating..."
	selected := *row
	ctx := m.ctx
	fn := m.generateFn
	return m, func() tea.Msg {
		updated, err := fn(ctx, selected)
		if err != nil {
			return generateErrMsg{err: err}
		}
		return generateDoneMsg{row: updated}
	}
}

func (m rootModel) View() string {
	var b strings.Builder

	// Filter bar
	b.WriteString(m.renderFilterBar())
	b.WriteString("\n\n")

	listWidth := m.listWidth()
	detailWidth := m.detailWidth()
	contentHeight := m.contentHeight()

	// List pane
	listPane := m.renderListPane(listWidth, contentHeight)

	// Detail pane
	detailPane := m.renderDetailPane(detailWidth, contentHeight)

	// Join horizontally
	split := lipgloss.JoinHorizontal(lipgloss.Top, listPane, detailPane)
	b.WriteString(split)
	b.WriteString("\n")

	// Status bar
	b.WriteString(m.renderStatusBar())

	return b.String()
}

// --- Filter bar ---

func (m rootModel) renderFilterBar() string {
	sep := m.styles.render(m.styles.filterSeparator, " │ ")

	// TIME filter
	timeLabels := []struct {
		filter timeFilter
		label  string
	}{
		{timeFilter24h, "24h"},
		{timeFilter7d, "7d"},
		{timeFilter30d, "30d"},
		{timeFilterAll, "all"},
	}
	var timeParts []string
	for _, item := range timeLabels {
		if item.filter == m.timeFilter {
			timeParts = append(timeParts, m.styles.render(m.styles.filterActive, item.label))
		} else {
			timeParts = append(timeParts, m.styles.render(m.styles.filterInactive, item.label))
		}
	}
	timeStr := m.styles.render(m.styles.filterLabel, "TIME: ") + strings.Join(timeParts, sep)

	// BRANCH filter
	branchLabels := []struct {
		filter branchFilter
		label  string
	}{
		{filterCurrentBranch, "current"},
		{filterRepo, "repo"},
	}
	var branchParts []string
	for _, item := range branchLabels {
		if item.filter == m.branchFilter {
			branchParts = append(branchParts, m.styles.render(m.styles.filterActive, item.label))
		} else {
			branchParts = append(branchParts, m.styles.render(m.styles.filterInactive, item.label))
		}
	}
	branchStr := m.styles.render(m.styles.filterLabel, "BRANCH: ") + strings.Join(branchParts, sep)

	count := m.styles.render(m.styles.sessionCount, fmt.Sprintf("%d sessions", len(m.filteredRows)))

	return timeStr + "    " + branchStr + "    " + count
}

// --- List pane ---

func (m rootModel) renderListPane(width, height int) string {
	var b strings.Builder

	// Column header
	header := m.formatListRow("TIME", "CKPT", "AGENT", width)
	b.WriteString(m.styles.render(m.styles.listHeader, header))
	b.WriteString("\n")
	b.WriteString(strings.Repeat("─", width))
	b.WriteString("\n")

	pageRows := m.currentPageRows()
	listHeight := height - 2 // header + separator

	for i, row := range pageRows {
		if i >= listHeight {
			break
		}
		timeStr := row.CreatedAt.Format("01-02 15:04")
		checkpoint := row.CheckpointID
		if len(checkpoint) > 6 {
			checkpoint = checkpoint[:6]
		}
		agent := truncate(row.Agent, 14)
		line := m.formatListRow(timeStr, checkpoint, agent, width)

		if i == m.cursor {
			// Selected: amber text + dark background + left accent
			accent := m.styles.render(m.styles.listAccent, "▸ ")
			styled := m.styles.render(m.styles.listSelected, line)
			if m.styles.colorEnabled {
				styled = m.styles.listSelectedBg.Render(styled)
			}
			b.WriteString(accent + styled)
		} else {
			b.WriteString("  " + m.styles.render(m.styles.listNormal, line))
		}
		b.WriteString("\n")
	}

	// Fill remaining lines
	for i := len(pageRows); i < listHeight; i++ {
		b.WriteString("\n")
	}

	// Page indicator
	pageInfo := m.styles.render(m.styles.dim, fmt.Sprintf("%d/%d", m.paginator.Page+1, max(1, m.paginator.TotalPages)))
	b.WriteString(m.styles.render(m.styles.dim, "←→ ") + pageInfo)

	return b.String()
}

func (m rootModel) formatListRow(time, ckpt, agent string, _ int) string {
	return fmt.Sprintf("%-11s %-6s %-14s", time, ckpt, agent)
}

// --- Detail pane ---

func (m rootModel) renderDetailPane(width, _ int) string {
	var b strings.Builder

	// Column header aligned with list pane header
	b.WriteString(m.styles.render(m.styles.listHeader, "Details"))
	b.WriteString("\n")
	b.WriteString(strings.Repeat("─", width))
	b.WriteString("\n")

	row := m.selectedRow()
	if row == nil {
		b.WriteString(m.styles.render(m.styles.emptyState, "  No sessions to display"))
		return b.String()
	}

	// Fixed metadata header
	header := renderMetadataHeader(m.styles, *row, width)
	b.WriteString(header)
	b.WriteString("\n\n")

	// Scrollable viewport (sized in resize())
	b.WriteString(m.detailVP.View())

	return b.String()
}

func (m rootModel) renderStatusBar() string {
	var parts []string
	parts = append(parts, "j/k navigate")
	parts = append(parts, "pgup/dn scroll")
	parts = append(parts, "1 time")
	parts = append(parts, "2 branch")
	parts = append(parts, "←→ page")
	if m.generateFn != nil {
		parts = append(parts, "g generate")
	}
	parts = append(parts, "q quit")
	status := strings.Join(parts, "  ")

	if m.genStatus != "" {
		style := m.styles.filterActive
		if strings.HasPrefix(m.genStatus, "Error:") {
			style = m.styles.errorText
		}
		status = m.styles.render(style, m.genStatus) + "  " + status
	}

	return m.styles.render(m.styles.statusBar, status)
}

// --- Layout helpers ---

func (m rootModel) listWidth() int {
	return max(30, m.width*30/100)
}

func (m rootModel) detailWidth() int {
	return max(30, m.width-m.listWidth()-1)
}

func (m rootModel) contentHeight() int {
	return max(5, m.height-verticalChrome)
}

// --- Data management ---

func (m *rootModel) updateRowData(updated insightsdb.SessionRow) {
	for i, row := range m.branchRows {
		if row.SessionID == updated.SessionID {
			m.branchRows[i] = updated
			break
		}
	}
	for i, row := range m.repoRows {
		if row.SessionID == updated.SessionID {
			m.repoRows[i] = updated
			break
		}
	}
	for i, row := range m.filteredRows {
		if row.SessionID == updated.SessionID {
			m.filteredRows[i] = updated
			break
		}
	}
}

func (m *rootModel) rebuildFilteredRows() {
	m.filteredRows = m.applyFilter()
	m.paginator.PerPage = m.pageSize
	totalPages := m.paginator.SetTotalPages(len(m.filteredRows))
	if totalPages == 0 {
		m.paginator.TotalPages = 1
	}
	if m.paginator.Page >= m.paginator.TotalPages {
		m.paginator.Page = max(0, m.paginator.TotalPages-1)
	}
	if m.paginator.Page < 0 {
		m.paginator.Page = 0
	}
	if m.cursor >= len(m.currentPageRows()) {
		m.cursor = max(0, len(m.currentPageRows())-1)
	}
}

func (m rootModel) applyFilter() []insightsdb.SessionRow {
	// Select source rows based on branch filter scope.
	var source []insightsdb.SessionRow
	switch m.branchFilter {
	case filterCurrentBranch:
		source = m.branchRows
	case filterRepo:
		source = m.repoRows
	}

	filtered := make([]insightsdb.SessionRow, 0, len(source))
	now := time.Now()
	for _, row := range source {
		// Time filter
		switch m.timeFilter {
		case timeFilter24h:
			if now.Sub(row.CreatedAt) > 24*time.Hour {
				continue
			}
		case timeFilter7d:
			if now.Sub(row.CreatedAt) > 7*24*time.Hour {
				continue
			}
		case timeFilter30d:
			if now.Sub(row.CreatedAt) > 30*24*time.Hour {
				continue
			}
		case timeFilterAll:
			// no time filtering
		}

		// Current-branch view still filters by branch name.
		if m.branchFilter == filterCurrentBranch && m.currentBranch != "" && row.Branch != m.currentBranch {
			continue
		}

		filtered = append(filtered, row)
	}
	return filtered
}

func (m rootModel) currentPageRows() []insightsdb.SessionRow {
	if len(m.filteredRows) == 0 {
		return nil
	}
	start, end := m.paginator.GetSliceBounds(len(m.filteredRows))
	if start >= len(m.filteredRows) {
		return nil
	}
	if end > len(m.filteredRows) {
		end = len(m.filteredRows)
	}
	return m.filteredRows[start:end]
}

func (m rootModel) selectedRow() *insightsdb.SessionRow {
	rows := m.currentPageRows()
	if m.cursor < 0 || m.cursor >= len(rows) {
		return nil
	}
	return &rows[m.cursor]
}

// --- Navigation ---

func (m *rootModel) moveCursor(delta int) {
	pageRows := m.currentPageRows()
	if len(pageRows) == 0 {
		return
	}
	m.cursor += delta
	if m.cursor < 0 {
		m.cursor = 0
	}
	if m.cursor >= len(pageRows) {
		m.cursor = len(pageRows) - 1
	}
	m.genStatus = "" // clear status on navigation
	m.updateDetailViewport()
}

func (m *rootModel) cycleTime() {
	m.timeFilter = (m.timeFilter + 1) % 4
	m.paginator.Page = 0
	m.cursor = 0
	m.genStatus = ""
	m.rebuildFilteredRows()
	m.updateDetailViewport()
}

func (m *rootModel) cycleBranch() {
	m.branchFilter = (m.branchFilter + 1) % 2
	m.paginator.Page = 0
	m.cursor = 0
	m.genStatus = ""
	m.rebuildFilteredRows()
	m.updateDetailViewport()
}

func (m *rootModel) nextPage() {
	if m.paginator.OnLastPage() {
		return
	}
	m.paginator.NextPage()
	m.cursor = 0
	m.genStatus = ""
	m.updateDetailViewport()
}

func (m *rootModel) prevPage() {
	if m.paginator.OnFirstPage() {
		return
	}
	m.paginator.PrevPage()
	m.cursor = 0
	m.genStatus = ""
	m.updateDetailViewport()
}

func (m *rootModel) updateDetailViewport() {
	row := m.selectedRow()
	if row == nil {
		m.detailVP.SetContent("")
		return
	}
	content := renderDetailContent(m.styles, *row, m.detailWidth())
	m.detailVP.SetContent(content)
}

func (m *rootModel) resize(width, height int) {
	selectedSessionID := ""
	if selected := m.selectedRow(); selected != nil {
		selectedSessionID = selected.SessionID
	}

	m.width = width
	m.height = height

	contentHeight := m.contentHeight()
	listHeight := contentHeight - 2 // header + separator
	m.pageSize = max(1, listHeight)

	// Detail viewport: subtract detail header (1) + separator (1) + metadata header (~3) + blank line (1) = 6
	vp := viewport.New(m.detailWidth(), max(3, contentHeight-6))
	vp.MouseWheelEnabled = false
	m.detailVP = vp

	m.rebuildFilteredRows()
	m.restoreSelection(selectedSessionID)
	m.updateDetailViewport()
}

func (m *rootModel) restoreSelection(sessionID string) {
	if sessionID == "" || len(m.filteredRows) == 0 {
		return
	}

	for idx, row := range m.filteredRows {
		if row.SessionID != sessionID {
			continue
		}

		m.paginator.Page = idx / m.pageSize
		cursor := idx % m.pageSize
		pageRows := m.currentPageRows()
		if len(pageRows) > 0 && cursor >= len(pageRows) {
			cursor = len(pageRows) - 1
		}
		m.cursor = cursor
		return
	}
}

